from pathlib import Path
p=Path('index.html')
s=p.read_text()
# Add reporting panel to block quiz, matching the standard quiz UX.
old='<h2 id="blockQuizQuestion"></h2><div id="blockQuizAnswers"></div><div id="blockQuizFeedback"></div><div class="quiz-actions"><button class="primary" id="blockQuizNext" type="button" disabled>Następne →</button></div></section>'
new='<div class="quiz-main"><div><div id="blockPublicIssueCounts" class="public-issue-counts" aria-live="polite"></div><h2 id="blockQuizQuestion"></h2><div id="blockQuizAnswers"></div><div id="blockQuizFeedback"></div><div class="quiz-actions"><button class="primary" id="blockQuizNext" type="button" disabled>Następne →</button></div></div><aside class="quiz-side"><button class="report secondary" id="blockOutdated" type="button">⚑ Nieaktualne pytanie</button><button class="report secondary" id="blockWrong" type="button">⚑ Błąd</button><label for="blockComment" class="muted">Dodaj komentarz</label><div id="blockCommentIdentity" class="muted small"></div><input id="blockComment" autocomplete="off" maxlength="180" placeholder="Np. zmienił się przepis / odpowiedź B jest błędna"><p id="blockReportStatus" class="muted"></p><div class="comment-actions"><button class="primary" id="blockSendComment" type="button">Wyślij komentarz</button><button class="secondary" id="blockRefreshComments" type="button">Odśwież</button><button class="danger" id="blockDeleteComment" type="button">Usuń mój komentarz</button></div><div id="blockCommentHistory" class="muted"></div></aside></div></section>'
assert old in s
s=s.replace(old,new)
# Add active report list to new-exam admin sidebar.
old='<aside class="exam-counts"><h3>Liczba pytań w blokach</h3><div id="examBlockCounts"></div></aside>'
new='<aside class="exam-counts"><h3>Liczba pytań w blokach</h3><div id="examBlockCounts"></div><hr style="border-color:#334155;margin:18px 0"><h3>Aktywne zgłoszenia <span id="examIssueCount">0</span></h3><div id="examIssues" class="exam-list"></div></aside>'
assert old in s
s=s.replace(old,new)
# State for the separate exam reports table.
s=s.replace("let bank=[],examBank=[],session=[],i=0,chosen={},mistakes=new Set(),user=null,reports={},publicComments={},publicIssueCounts={};", "let bank=[],examBank=[],session=[],i=0,chosen={},mistakes=new Set(),user=null,reports={},publicComments={},publicIssueCounts={},examReports={},examPublicComments={},examPublicIssueCounts={};")
# Load exam report data alongside exam questions.
s=s.replace("renderExamList();renderExamCounts();renderBlockTests();renderExamReadiness()}", "renderExamList();renderExamCounts();renderBlockTests();renderExamReadiness();if(user){await loadExamReports();await loadExamPublicComments();await loadExamPublicReportCounts();if(!user.is_anonymous)await renderExamIssues()}}")
# Insert exam-report helpers before block readiness.
marker='function renderExamReadiness()'
idx=s.index(marker)
helpers=r'''async function loadExamPublicComments(){let r=await sb.from('exam_issue_reports').select('id,question_id,reporter_id,comment,display_name,created_at').eq('report_type','comment').eq('active',true).not('comment','is',null).order('created_at',{ascending:true});if(r.error){console.error('Exam public comments:',r.error);return}examPublicComments={};(r.data||[]).forEach(x=>{(examPublicComments[x.question_id]??=[]).push(x)})}
async function loadExamPublicReportCounts(){let r=await sb.from('exam_issue_reports').select('question_id,report_type').eq('active',true).in('report_type',['outdated','wrong']);if(r.error){console.error('Exam report counts:',r.error);return}examPublicIssueCounts={};(r.data||[]).forEach(x=>{if(!examPublicIssueCounts[x.question_id])examPublicIssueCounts[x.question_id]={outdated:0,wrong:0};examPublicIssueCounts[x.question_id][x.report_type]++});if(blockSession[blockIndex])renderBlockPublicIssueCounts(blockSession[blockIndex].id)}
async function loadExamReports(){if(!user)return;let name=(localStorage.getItem(NAME_KEY)||'').trim(),r=await sb.from('exam_issue_reports').select('*').eq('reporter_id',user.id).order('created_at',{ascending:false});examReports={};(r.data||[]).forEach(x=>{let n=(x.display_name||'').trim().toLocaleLowerCase('pl-PL');if(name&&n!==name.toLocaleLowerCase('pl-PL'))return;let key=x.question_id+'|'+x.report_type+'|'+n;if(!examReports[key])examReports[key]=x})}
function renderBlockPublicIssueCounts(questionId){let box=$('blockPublicIssueCounts');if(!box)return;let c=examPublicIssueCounts[questionId]||{outdated:0,wrong:0};box.innerHTML='';if(c.outdated){let b=document.createElement('span');b.textContent='⚑ Nieaktualne pytanie: '+c.outdated;box.appendChild(b)}if(c.wrong){let b=document.createElement('span');b.textContent='⚑ Błąd: '+c.wrong;box.appendChild(b)}}
async function reportExamQuestion(type){if(!user){$('blockReportStatus').textContent='Brak sesji.';return}let name=(localStorage.getItem(NAME_KEY)||'').trim(),confirmed=localStorage.getItem(NAME_CONFIRMED_KEY)==='1'&&!!name;if(!confirmed){$('blockReportStatus').textContent='Najpierw wpisz i potwierdź swoją nazwę u góry strony.';return}let x=blockSession[blockIndex];if(!x)return;let key=x.id+'|'+type+'|'+name.toLocaleLowerCase('pl-PL'),old=examReports[key],active=!(old&&old.active),r;if(old)r=await sb.from('exam_issue_reports').update({active,display_name:name}).eq('id',old.id).eq('reporter_id',user.id);else r=await sb.from('exam_issue_reports').insert({question_id:x.id,reporter_id:user.id,report_type:type,active:true,comment:null,display_name:name});if(r.error){$('blockReportStatus').textContent='Błąd zgłoszenia: '+r.error.message;return}await loadExamReports();await loadExamPublicReportCounts();renderBlockQuestion();$('blockReportStatus').textContent=''}
async function sendExamComment(){let x=blockSession[blockIndex];if(!x||!user)return;let name=(localStorage.getItem(NAME_KEY)||'').trim(),confirmed=localStorage.getItem(NAME_CONFIRMED_KEY)==='1'&&!!name;if(!confirmed){$('blockReportStatus').textContent='Najpierw wpisz i potwierdź swoją nazwę u góry strony.';return}let text=$('blockComment').value.trim();if(!text){$('blockReportStatus').textContent='Wpisz wiadomość przed wysłaniem.';return}let r=await sb.from('exam_issue_reports').insert({question_id:x.id,reporter_id:user.id,report_type:'comment',active:true,comment:text,display_name:name});if(r.error){$('blockReportStatus').textContent='Błąd wysyłania: '+r.error.message;return}await loadExamReports();await loadExamPublicComments();renderBlockQuestion();$('blockReportStatus').textContent=''}
async function deleteExamComment(){let x=blockSession[blockIndex];if(!x||!user)return;let name=(localStorage.getItem(NAME_KEY)||'').trim().toLocaleLowerCase('pl-PL'),r=(examPublicComments[x.id]||[]).find(z=>(z.display_name||'').trim().toLocaleLowerCase('pl-PL')===name&&z.reporter_id===user.id);if(!r){$('blockReportStatus').textContent='Nie znaleziono Twojego komentarza.';return}let u=await sb.from('exam_issue_reports').update({active:false}).eq('id',r.id).eq('reporter_id',user.id);if(u.error){$('blockReportStatus').textContent='Błąd usuwania: '+u.error.message;return}await loadExamReports();await loadExamPublicComments();renderBlockQuestion()}
async function renderExamIssues(){if(!$('examIssues'))return;let r=await sb.from('exam_issue_reports').select('*').eq('active',true).order('created_at',{ascending:false});if(r.error){$('examIssues').innerHTML='<p class="muted">Błąd pobierania zgłoszeń.</p>';return}let groups={};(r.data||[]).forEach(x=>{(groups[x.question_id]??=[]).push(x)});let rows=Object.values(groups);$('examIssueCount').textContent=rows.length;$('examIssues').innerHTML=rows.length?rows.map(h=>{let q=examBank.find(q=>q.id===h[0].question_id),comments=h.filter(x=>x.report_type==='comment'&&x.comment),outdated=h.filter(x=>x.report_type==='outdated'),wrong=h.filter(x=>x.report_type==='wrong');return '<div class="issue"><b>#'+(q?.number??'?')+' '+esc(q?.text||'Pytanie usunięte')+'</b><br><small>Blok '+(q?.block_id??'—')+' · Nieaktualne: '+outdated.length+' · Błąd: '+wrong.length+' · Komentarze: '+comments.length+'</small>'+(comments.length?'<div class="comment-history">'+comments.map(z=>'<p><b>'+esc(z.display_name||'Nazwa niepodana')+'</b><br>'+esc(z.comment)+'</p>').join('')+'</div>':'')+'<button class="secondary" type="button" onclick="cancelExamIssue(\''+h[0].question_id+'\')">Anuluj zgłoszenia</button></div>'}).join(''):'<p class="muted">Brak aktywnych zgłoszeń.</p>'}
async function cancelExamIssue(questionId){let r=await sb.from('exam_issue_reports').update({active:false}).eq('question_id',questionId).eq('active',true);if(r.error){alert(r.error.message);return}await loadExamReports();await loadExamPublicComments();await loadExamPublicReportCounts();await renderExamIssues();if(blockSession[blockIndex])renderBlockQuestion()}
'''
s=s[:idx]+helpers+s[idx:]
# Enrich block question rendering with reports/comments state.
needle="function renderBlockQuestion(){let q=blockSession[blockIndex];if(!q)return;$('blockQuizLabel')"
repl="function renderBlockQuestion(){let q=blockSession[blockIndex];if(!q)return;renderBlockPublicIssueCounts(q.id);let name=(localStorage.getItem(NAME_KEY)||'').trim(),confirmed=localStorage.getItem(NAME_CONFIRMED_KEY)==='1'&&!!name,reportName=name.toLocaleLowerCase('pl-PL'),comments=examPublicComments[q.id]||[];$('blockCommentIdentity').textContent='Komentarz zostanie wysłany jako: '+(confirmed?name:'—');$('blockComment').value='';$('blockCommentHistory').innerHTML=comments.length?'<details class=\"comment-history\" open><summary>Komentarze ('+comments.length+')</summary>'+comments.map(z=>'<p style=\"margin:8px 0\"><b>'+esc(z.display_name||'Nazwa niepodana')+'</b> <small>'+new Date(z.created_at).toLocaleString('pl-PL')+'</small><br>'+esc(z.comment)+'</p>').join('')+'</details>':'';['outdated','wrong'].forEach(t=>{let r=examReports[q.id+'|'+t+'|'+reportName],id=t==='outdated'?'blockOutdated':'blockWrong';$(id).classList.toggle('on',!!(r&&r.active));$(id).classList.toggle('primary',!!(r&&r.active));$(id).classList.toggle('secondary',!(r&&r.active))});$('blockQuizLabel')"
assert needle in s
s=s.replace(needle,repl)
# Event handlers.
needle="$('blockQuizNext').onclick=()=>blockIndex<blockSession.length-1?(blockIndex++,renderBlockQuestion()):finishBlockTest();"
insert="$('blockOutdated').onclick=()=>reportExamQuestion('outdated');$('blockWrong').onclick=()=>reportExamQuestion('wrong');$('blockSendComment').onclick=sendExamComment;$('blockRefreshComments').onclick=async()=>{await loadExamPublicComments();await loadExamPublicReportCounts();await loadExamReports();renderBlockQuestion()};$('blockDeleteComment').onclick=deleteExamComment;$('blockComment').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();sendExamComment()}});"
assert needle in s
s=s.replace(needle,insert+needle)
# Realtime for the new reports table.
needle="let issueChannel=null;function subscribeIssueUpdates()"
repl="let examIssueChannel=null;function subscribeExamIssueUpdates(){if(examIssueChannel)sb.removeChannel(examIssueChannel);examIssueChannel=sb.channel('exam-issue-reports-live').on('postgres_changes',{event:'*',schema:'public',table:'exam_issue_reports'},async()=>{await loadExamPublicReportCounts();await loadExamPublicComments();if(user&&!user.is_anonymous)await renderExamIssues();if(blockSession[blockIndex])renderBlockQuestion()}).subscribe()}\nlet issueChannel=null;function subscribeIssueUpdates()"
assert needle in s
s=s.replace(needle,repl)
# Start realtime for admin and anonymous sessions.
s=s.replace("await loadReports();await loadPublicComments();return", "await loadReports();await loadPublicComments();await loadExamReports();await loadExamPublicComments();await loadExamPublicReportCounts();subscribeExamIssueUpdates();return")
s=s.replace("await loadReports();await loadPublicComments()}catch", "await loadReports();await loadPublicComments();await loadExamReports();await loadExamPublicComments();await loadExamPublicReportCounts();subscribeExamIssueUpdates()}catch")
s=s.replace("await renderIssues();subscribeIssueUpdates()", "await renderIssues();await renderExamIssues();subscribeIssueUpdates();subscribeExamIssueUpdates()")
p.write_text(s)
